import{_ as n,a0 as s,w as a,s as r,ao as p,I as d,x as t,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"面向系统管理员的网络管理指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向系统管理员的网络管理指南 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向系统管理员的网络管理指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向系统管理员的网络管理指南 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180709 A sysadmin-s guide to network management","title":"面向系统管理员的网络管理指南","tag":"201808","desc":""},"relativePath":"201808/20180709 A sysadmin-s guide to network management.md","filePath":"[post].md"}'),c={name:"201808/20180709 A sysadmin-s guide to network management.md"};function u(g,e,m,f,P,h){const o=s("Link");return a(),r("div",null,[e[28]||(e[28]=p('<h1 id="面向系统管理员的网络管理指南" tabindex="-1">面向系统管理员的网络管理指南 <a class="header-anchor" href="#面向系统管理员的网络管理指南" aria-label="Permalink to “面向系统管理员的网络管理指南”">​</a></h1><blockquote><p>一个使管理服务器和网络更轻松的 Linux 工具和命令的参考列表。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/openwires_fromRHT_520_0612LL.png?itok=PqZi55Ab" alt=""></p><p>如果你是一位系统管理员，那么你的日常工作应该包括管理服务器和数据中心的网络。以下的 Linux 实用工具和命令 —— 从基础的到高级的 —— 将帮你更轻松地管理你的网络。</p><p>在几个命令中，你将会看到 <code>&lt;fqdn&gt;</code>，它是“完全合格域名”的全称。当你看到它时，你应该用你的网站 URL 或你的服务器来代替它（比如，<code>server-name.company.com</code>），具体要视情况而定。</p><h3 id="ping" tabindex="-1">Ping <a class="header-anchor" href="#ping" aria-label="Permalink to “Ping”">​</a></h3>',6)),d("p",null,[e[2]||(e[2]=t("正如它的名字所表示的那样，",-1)),e[3]||(e[3]=d("code",null,"ping",-1)),e[4]||(e[4]=t(" 是用于去检查从你的系统到你想去连接的系统之间端到端的连通性。当一个 ping 成功时，它使用的 ",-1)),l(o,{href:"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol"},{default:i(()=>[...e[0]||(e[0]=[t("ICMP",-1)])]),_:1}),e[5]||(e[5]=t(" 的 echo 包将会返回到你的系统中。它是检查系统/网络连通性的一个良好开端。你可以在 IPv4 和 IPv6 地址上使用 ",-1)),e[6]||(e[6]=d("code",null,"ping",-1)),e[7]||(e[7]=t(' 命令。（阅读我的文章 "',-1)),l(o,{href:"https://opensource.com/article/18/5/how-find-ip-address-linux"},{default:i(()=>[...e[1]||(e[1]=[t("如何在 Linux 系统上找到你的 IP 地址",-1)])]),_:1}),e[8]||(e[8]=t('" 去学习更多关于 IP 地址的知识）',-1))]),e[29]||(e[29]=p('<p><strong>语法：</strong></p><ul><li>IPv4: <code>ping &lt;ip address&gt;/&lt;fqdn&gt;</code></li><li>IPv6: <code>ping6 &lt;ip address&gt;/&lt;fqdn&gt;</code></li></ul><p>你也可以使用 <code>ping</code> 去解析出网站所对应的 IP 地址，如下图所示：</p><p><img src="https://opensource.com/sites/default/files/uploads/ping-screen-0.png" alt=""></p><h3 id="traceroute" tabindex="-1">Traceroute <a class="header-anchor" href="#traceroute" aria-label="Permalink to “Traceroute”">​</a></h3><p><code>ping</code> 是用于检查端到端的连通性，<code>traceroute</code> 实用工具将告诉你到达对端系统、网站、或服务器所经过的路径上所有路由器的 IP 地址。<code>traceroute</code> 在网络连接调试中经常用于在 <code>ping</code> 之后的第二步。</p><p>这是一个跟踪从你的系统到其它对端的全部网络路径的非常好的工具。在检查端到端的连通性时，这个实用工具将告诉你到达对端系统、网站、或服务器上所经历的路径上的全部路由器的 IP 地址。通常用于网络连通性调试的第二步。</p><p><strong>语法：</strong></p><ul><li><code>traceroute &lt;ip address&gt;/&lt;fqdn&gt;</code></li></ul><h3 id="telnet" tabindex="-1">Telnet <a class="header-anchor" href="#telnet" aria-label="Permalink to “Telnet”">​</a></h3><p><strong>语法：</strong></p>',11)),d("ul",null,[d("li",null,[e[10]||(e[10]=d("code",null,"telnet <ip address>/<fqdn>",-1)),e[11]||(e[11]=t(" 是用于 ",-1)),l(o,{href:"https://en.wikipedia.org/wiki/Telnet"},{default:i(()=>[...e[9]||(e[9]=[t("telnet",-1)])]),_:1}),e[12]||(e[12]=t(" 进入任何支持该协议的服务器。",-1))])]),e[30]||(e[30]=p('<h3 id="netstat" tabindex="-1">Netstat <a class="header-anchor" href="#netstat" aria-label="Permalink to “Netstat”">​</a></h3><p>这个网络统计（<code>netstat</code>）实用工具是用于去分析解决网络连接问题和检查接口/端口统计数据、路由表、协议状态等等的。它是任何管理员都应该必须掌握的工具。</p><p><strong>语法：</strong></p><ul><li><code>netstat -l</code> 显示所有处于监听状态的端口列表。</li><li><code>netstat -a</code> 显示所有端口；如果去指定仅显示 TCP 端口，使用 <code>-at</code>（指定信显示 UDP 端口，使用 <code>-au</code>）。</li><li><code>netstat -r</code> 显示路由表。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-r.png" alt=""></p><ul><li><code>netstat -s</code> 显示每个协议的状态总结。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-s.png" alt=""></p><ul><li><code>netstat -i</code> 显示每个接口传输/接收（TX/RX）包的统计数据。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-i.png" alt=""></p><h3 id="nmcli" tabindex="-1">Nmcli <a class="header-anchor" href="#nmcli" aria-label="Permalink to “Nmcli”">​</a></h3><p><code>nmcli</code> 是一个管理网络连接、配置等工作的非常好的实用工具。它能够去管理网络管理程序和修改任何设备的网络配置详情。</p><p><strong>语法：</strong></p><ul><li><code>nmcli device</code> 列出网络上的所有设备。</li><li><code>nmcli device show &lt;interface&gt;</code> 显示指定接口的网络相关的详细情况。</li><li><code>nmcli connection</code> 检查设备的连接情况。</li><li><code>nmcli connection down &lt;interface&gt;</code> 关闭指定接口。</li><li><code>nmcli connection up &lt;interface&gt;</code> 打开指定接口。</li><li><code>nmcli con add type vlan con-name &lt;connection-name&gt; dev &lt;interface&gt; id &lt;vlan-number&gt; ipv4 &lt;ip/cidr&gt; gw4 &lt;gateway-ip&gt;</code> 在特定的接口上使用指定的 VLAN 号添加一个虚拟局域网（VLAN）接口、IP 地址、和网关。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/nmcli.png" alt=""></p><h3 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to “路由”">​</a></h3><p>检查和配置路由的命令很多。下面是其中一些比较有用的：</p><p><strong>语法：</strong></p><ul><li><code>ip route</code> 显示各自接口上所有当前的路由配置。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/ip-route.png" alt=""></p><ul><li><code>route add default gw &lt;gateway-ip&gt;</code> 在路由表中添加一个默认的网关。</li><li><code>route add -net &lt;network ip/cidr&gt; gw &lt;gateway ip&gt; &lt;interface&gt;</code> 在路由表中添加一个新的网络路由。还有许多其它的路由参数，比如，添加一个默认路由，默认网关等等。</li><li><code>route del -net &lt;network ip/cidr&gt;</code> 从路由表中删除一个指定的路由条目。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/route-add-del.png" alt=""></p><ul><li><p><code>ip neighbor</code> 显示当前的邻接表和用于去添加、改变、或删除新的邻居。</p><p><img src="https://opensource.com/sites/default/files/uploads/ip-neighbor.png" alt=""></p><p><img src="https://opensource.com/sites/default/files/uploads/ip-neigh-help.png" alt=""></p></li><li><p><code>arp</code> （它的全称是 “地址解析协议”）类似于 <code>ip neighbor</code>。<code>arp</code> 映射一个系统的 IP 地址到它相应的 MAC（介质访问控制）地址。</p><p><img src="https://opensource.com/sites/default/files/uploads/arp.png" alt=""></p></li></ul><h3 id="tcpdump-和-wireshark" tabindex="-1">Tcpdump 和 Wireshark <a class="header-anchor" href="#tcpdump-和-wireshark" aria-label="Permalink to “Tcpdump 和 Wireshark”">​</a></h3><p>Linux 提供了许多包捕获工具，比如 <code>tcpdump</code>、<code>wireshark</code>、<code>tshark</code> 等等。它们被用于去捕获传输/接收的网络流量中的数据包，因此它们对于系统管理员去诊断丢包或相关问题时非常有用。对于热衷于命令行操作的人来说，<code>tcpdump</code> 是一个非常好的工具，而对于喜欢 GUI 操作的用户来说，<code>wireshark</code> 是捕获和分析数据包的不二选择。<code>tcpdump</code> 是一个 Linux 内置的用于去捕获网络流量的实用工具。它能够用于去捕获/显示特定端口、协议等上的流量。</p><p><strong>语法：</strong></p><ul><li><p><code>tcpdump -i &lt;interface-name&gt;</code> 显示指定接口上实时通过的数据包。通过在命令中添加一个 <code>-w</code> 标志和输出文件的名字，可以将数据包保存到一个文件中。例如：<code>tcpdump -w &lt;output-file.&gt; -i &lt;interface-name&gt;</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/tcpdump-i.png" alt=""></p></li><li><p><code>tcpdump -i &lt;interface&gt; src &lt;source-ip&gt;</code> 从指定的源 IP 地址上捕获数据包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; dst &lt;destination-ip&gt;</code> 从指定的目标 IP 地址上捕获数据包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; port &lt;port-number&gt;</code> 从一个指定的端口号（比如，53、80、8080 等等）上捕获数据包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; &lt;protocol&gt;</code> 捕获指定协议的数据包，比如：TCP、UDP、等等。</p></li></ul><h3 id="iptables" tabindex="-1">Iptables <a class="header-anchor" href="#iptables" aria-label="Permalink to “Iptables”">​</a></h3><p><code>iptables</code> 是一个包过滤防火墙工具，它能够允许或阻止某些流量。这个实用工具的应用范围非常广泛；下面是它的其中一些最常用的使用命令。</p><p><strong>语法：</strong></p><ul><li><code>iptables -L</code> 列出所有已存在的 <code>iptables</code> 规则。</li><li><code>iptables -F</code> 删除所有已存在的规则。</li></ul><p>下列命令允许流量从指定端口到指定接口：</p><ul><li><code>iptables -A INPUT -i &lt;interface&gt; -p tcp –dport &lt;port-number&gt; -m state –state NEW,ESTABLISHED -j ACCEPT</code></li><li><code>iptables -A OUTPUT -o &lt;interface&gt; -p tcp -sport &lt;port-number&gt; -m state – state ESTABLISHED -j ACCEPT</code></li></ul><p>下列命令允许<ruby>环回<rt>loopback</rt></ruby>接口访问系统：</p><ul><li><code>iptables -A INPUT -i lo -j ACCEPT</code></li><li><code>iptables -A OUTPUT -o lo -j ACCEPT</code></li></ul><h3 id="nslookup" tabindex="-1">Nslookup <a class="header-anchor" href="#nslookup" aria-label="Permalink to “Nslookup”">​</a></h3><p><code>nslookup</code> 工具是用于去获得一个网站或域名所映射的 IP 地址。它也能用于去获得你的 DNS 服务器的信息，比如，一个网站的所有 DNS 记录（具体看下面的示例）。与 <code>nslookup</code> 类似的一个工具是 <code>dig</code>（Domain Information Groper）实用工具。</p><p><strong>语法：</strong></p><ul><li><code>nslookup &lt;website-name.com&gt;</code> 显示你的服务器组中 DNS 服务器的 IP 地址，它后面就是你想去访问网站的 IP 地址。</li><li><code>nslookup -type=any &lt;website-name.com&gt;</code> 显示指定网站/域中所有可用记录。</li></ul><h3 id="网络-接口调试" tabindex="-1">网络/接口调试 <a class="header-anchor" href="#网络-接口调试" aria-label="Permalink to “网络/接口调试”">​</a></h3><p>下面是用于接口连通性或相关网络问题调试所需的命令和文件的汇总。</p><p><strong>语法：</strong></p><ul><li><code>ss</code> 是一个转储套接字统计数据的实用工具。</li><li><code>nmap &lt;ip-address&gt;</code>，它的全称是 “Network Mapper”，它用于扫描网络端口、发现主机、检测 MAC 地址，等等。</li><li><code>ip addr/ifconfig -a</code> 提供一个系统上所有接口的 IP 地址和相关信息。</li><li><code>ssh -vvv user@&lt;ip/domain&gt;</code> 允许你使用指定的 IP/域名和用户名通过 SSH 协议登入到其它服务器。<code>-vvv</code> 标志提供 SSH 登入到服务器过程中的 &quot;最详细的&quot; 信息。</li><li><code>ethtool -S &lt;interface&gt;</code> 检查指定接口上的统计数据。</li><li><code>ifup &lt;interface&gt;</code> 启动指定的接口。</li><li><code>ifdown &lt;interface&gt;</code> 关闭指定的接口</li><li><code>systemctl restart network</code> 重启动系统上的一个网络服务。</li><li><code>/etc/sysconfig/network-scripts/&lt;interface-name&gt;</code> 是一个对指定的接口设置 IP 地址、网络、网关等等的接口配置文件。DHCP 模式也可以在这里设置。</li><li><code>/etc/hosts</code> 这个文件包含自定义的主机/域名到 IP 地址的映射。</li><li><code>/etc/resolv.conf</code> 指定系统上的 DNS 服务器的 IP 地址。</li><li><code>/etc/ntp.conf</code> 指定 NTP 服务器域名。</li></ul><hr>',43)),d("p",null,[e[14]||(e[14]=t("via: ",-1)),l(o,{href:"https://opensource.com/article/18/7/sysadmin-guide-networking-commands"},{default:i(()=>[...e[13]||(e[13]=[t("https://opensource.com/article/18/7/sysadmin-guide-networking-commands",-1)])]),_:1})]),d("p",null,[e[19]||(e[19]=t("作者：",-1)),l(o,{href:"https://opensource.com/users/architmodi"},{default:i(()=>[...e[15]||(e[15]=[t("Archit Modi",-1)])]),_:1}),e[20]||(e[20]=t(" 选题：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[16]||(e[16]=[t("lujun9972",-1)])]),_:1}),e[21]||(e[21]=t(" 译者：",-1)),l(o,{href:"https://github.com/qhwdw"},{default:i(()=>[...e[17]||(e[17]=[t("qhwdw",-1)])]),_:1}),e[22]||(e[22]=t(" 校对：",-1)),l(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[25]||(e[25]=t("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[23]||(e[23]=[t("LCTT",-1)])]),_:1}),e[26]||(e[26]=t(" 原创编译，",-1)),l(o,{href:"https://linux.cn/"},{default:i(()=>[...e[24]||(e[24]=[t("Linux中国",-1)])]),_:1}),e[27]||(e[27]=t(" 荣誉推出",-1))])])}const w=n(c,[["render",u]]);export{k as __pageData,w as default};
